def check_dict_case(d):
    if not d:  # Return False if the dictionary is empty
        return False

    lower_case = True
    upper_case = True

    for key in d:
        if not isinstance(key, str):
            return False  # Ensure all keys are strings

        if not key.islower():
            lower_case = False
        if not key.isupper():
            upper_case = False

    return lower_case or upper_case
```

